// Both desktop and mobile use the same first-level Projects.
// One straightforward Projects menu, on both phone and computer.
// Every category name is a real link to its project options; no hover side flyouts.
function buildProjectDropdowns(){
  const menus=['projects-menu','mobile-projects-menu']
    .map(id=>document.getElementById(id)).filter(Boolean);
  if(!menus.length||menus.every(menu=>menu.dataset.projectMenuReady==='true'))return;
  let css=document.getElementById('expanded-projects-menu-style');
  if(!css){
    css=document.createElement('style');css.id='expanded-projects-menu-style';
    css.textContent=[
      '#projects-menu.projects-mega,#mobile-projects-menu.projects-mega{box-sizing:border-box;min-width:240px;max-width:calc(100vw - 20px);max-height:min(68vh,620px)!important;overflow-y:auto!important;overflow-x:hidden!important;overscroll-behavior:contain;padding:5px;z-index:120}',
      '#projects-menu.projects-mega>a.project-category-link,#mobile-projects-menu.projects-mega>a.project-category-link{display:block!important;color:#0b5aa6!important;font-weight:800!important;text-decoration:underline!important;text-underline-offset:3px;padding:11px 14px!important;line-height:1.35;border-radius:6px;white-space:normal}',
      '.projects-mega>a.project-category-link:hover,.projects-mega>a.project-category-link:focus-visible{background:#e8f1fa!important;color:#073c70!important}',
      '@media(max-width:820px){nav.nav .mobile-top-nav #mobile-projects-menu.projects-mega{position:fixed!important;left:10px!important;right:10px!important;width:calc(100vw - 20px)!important;max-width:calc(100vw - 20px)!important;max-height:65vh!important}}'
    ].join('');
    document.head.append(css);
  }
  for(const menu of menus){
    if(menu.dataset.projectMenuReady==='true')continue;
    menu.replaceChildren();menu.classList.add('projects-mega');
    for(const [id,label] of PROJECT_MAIN_ENTRIES){
      const link=document.createElement('a');
      link.className='project-category-link';
      link.href='/project.html?project='+encodeURIComponent(id);
      link.textContent=label;
      menu.append(link);
    }
    menu.dataset.projectMenuReady='true';
  }
}
document.addEventListener('DOMContentLoaded',()=>{
 buildProjectDropdowns();
 // Page-specific scripts replace the header on some routes. Restore the same
 // unified desktop/mobile menu whenever a replacement header appears.
 const observer=new MutationObserver(()=>{
  const menus=[document.getElementById('projects-menu'),document.getElementById('mobile-projects-menu')].filter(Boolean);
  if(menus.some(menu=>menu.dataset.projectMenuReady!=='true'))buildProjectDropdowns();
 });
 observer.observe(document.documentElement,{childList:true,subtree:true});
});

// Home-page rendering can replace the nav after DOMContentLoaded. A second
// idempotent pass on load keeps the Projects menu consistent everywhere.
window.addEventListener('load',()=>buildProjectDropdowns());

